Quickselect: partition around a pivot, recurse into the side containing the kth element. O(n) average.

```python
import random

def kth_largest(nums, k):
    target = len(nums) - k
    def quickselect(lo, hi):
        pivot = nums[random.randint(lo, hi)]
        i, j = lo, hi
        while i <= j:
            while nums[i] < pivot:
                i += 1
            while nums[j] > pivot:
                j -= 1
            if i <= j:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
                j -= 1
        if target <= j:
            return quickselect(lo, j)
        elif target >= i:
            return quickselect(i, hi)
        else:
            return nums[target]
    return quickselect(0, len(nums) - 1)
